// LocalCompletion is the event surface the chat handler exposes for
// out-of-band observers (notably the async LLM-as-a-judge evaluator,
// see internal/judge). It is intentionally tiny: only the fields a
// judge needs to score a response. The handler never imports judge —
// the observer plugs in from cmd/nexus/main.go.
type LocalCompletion struct {
	TraceParent string
	TraceState  string
	RequestID   string
	Instruction string
	Output      string
	LocalModel  string
}

// JudgeObserver is the hook the chat handler invokes when a
// RouteLocal request completes successfully. Implementations must be
// safe to call concurrently; the handler invokes them on the same
// goroutine that serves the request so the observer should not block
// long. The handler also enforces a body-size cap before invoking
// the hook so a runaway model cannot blow the observer's memory.
type JudgeObserver interface {
	Submit(LocalCompletion) bool
}

// JudgeObserverFunc adapts a plain function to the JudgeObserver
// interface so wiring from main.go stays a one-liner.
type JudgeObserverFunc func(LocalCompletion) bool

// Submit implements JudgeObserver.
func (f JudgeObserverFunc) Submit(c LocalCompletion) bool { f(c); return true }

// LatencyEvent is emitted to the LatencyObserver hook after every
// upstream response with timing metadata.
type LatencyEvent struct {
	Route          string
	LatencySeconds float64
	TTFTSeconds    float64
	IsError        bool
}

// LatencyObserver is called after each request completes with timing
// information for dashboards and alerting.
type LatencyObserver interface {
	ObserveLatency(LatencyEvent)
}

// LatencyObserverFunc adapts a plain function to the LatencyObserver
// interface so wiring from main.go stays a one-liner.
type LatencyObserverFunc func(LatencyEvent)

// ObserveLatency implements LatencyObserver.
func (f LatencyObserverFunc) ObserveLatency(e LatencyEvent) { f(e) }

// PipelineStageEvent carries per-stage timing breakdown for a single
// request (issue #300). Each field is integer milliseconds spent in
// that pipeline stage; 0 when the stage was skipped or not applicable.
//
// SLMConfidence and SLMTaskType carry the routing decision metadata
// (issue #425). Confidence is 0.0..1.0 from the judge-guided
// adaptive routing store; TaskType is the Categorize() bucket.
// Both are 0/"" when the SLM was not consulted (guardrail/DSL path).
type PipelineStageEvent struct {
	RAGRetrievalMs      int64
	PromptEngineeringMs int64
	TOONCompressionMs   int64
	SLMRoutingMs        int64
	UpstreamFirstByteMs int64 // TTFT minus all proxy overhead stages

